/* Independent password authentication via server proxy. No password or token browser storage. */
(()=>{
let current=null,mode='signin',adminData=null;
const screen=document.createElement('section');screen.id='account-access';screen.setAttribute('aria-label','Account access');screen.style.cssText='position:fixed;inset:0;z-index:9999;background:radial-gradient(ellipse at top right,#d1e9e2,transparent 65%),#edf3f2;overflow:auto;padding:clamp(16px,4vw,55px);box-sizing:border-box';document.body.append(screen);
function visible(show){screen.hidden=!show;document.querySelector('aside').inert=show;document.querySelector('main').inert=show;if(show)screen.scrollTop=0}
function panel(content,wide=false){visible(true);screen.innerHTML=`<div style="max-width:${wide?'1120':'900'}px;margin:auto"><div style="margin-bottom:24px"><span style="color:#11796e;font-weight:800;letter-spacing:2px">✚ FN CLINICAL CDS</span><h1 style="font-size:clamp(28px,5vw,42px);margin:14px 0">Coordinated care.<br>Controlled access.</h1><p>Independent application accounts · Synthetic training environment</p></div><section style="background:white;border:1px solid #dbe6e3;border-radius:20px;padding:clamp(18px,4vw,34px);max-width:${wide?'1120':'580'}px;box-shadow:0 15px 45px #133c3610">${content}</section></div>`;screen.querySelector('h1')?.setAttribute('tabindex','-1');screen.querySelector('h1')?.focus()}
async function req(path,method='GET',data){const r=await fetch('/api/access/'+path,{method,cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});let v;try{v=await r.json()}catch{throw Error('Account service unavailable. Check your internet connection.')}if(r.status===401&&path==='session')return null;if(!r.ok)throw Error(v.error||'Request failed');return v}
function notice(text){const el=screen.querySelector('#account-error');if(el)el.textContent=text}
function fields(){return `<label class="field">Full name / display name<input name="label" required maxlength="100" autocomplete="name"></label><label class="field">Username<input name="username" required minlength="3" maxlength="32" pattern="[a-zA-Z][a-zA-Z0-9_.\\-]{2,31}" autocomplete="username" placeholder="e.g. demo.physician"></label><label class="field">Requested role<select name="requestedRole"><option value="physician">Physician</option><option value="nurse">Nurse</option><option value="pharmacist">Pharmacist</option><option value="patient">Patient</option></select></label><label class="field">Staff ID / Patient ID<input name="externalId" required maxlength="60" placeholder="Use a fictional ID for this demonstration"></label><label><input name="syntheticOnly" type="checkbox" required> Synthetic training data only</label>`}
function auth(){panel(`<div style="display:flex;gap:12px;margin-bottom:24px"><button class="btn ${mode==='signin'?'primary':''}" id="account-signin">Sign in</button><button class="btn ${mode==='signup'?'primary':''}" id="account-signup">Sign up</button></div><h2>${mode==='signin'?'Welcome back':'Request an account'}</h2><p>${mode==='signin'?'Use your application credentials. No ChatGPT account is required.':'Create your credentials, verify your email if prompted, then sign in to submit your access request.'}</p><form id="access-form">${mode==='signup'?fields():''}<label class="field">${mode==='signin'?'Email or username':'Email'}<input name="login" type="${mode==='signin'?'text':'email'}" required autocomplete="${mode==='signin'?'username':'email'}" maxlength="254"></label><label class="field">Password<input name="password" type="password" required ${mode==='signup'?'minlength="12"':''} maxlength="256" autocomplete="${mode==='signin'?'current-password':'new-password'}"></label>${mode==='signup'?'<p>Use at least 12 characters. New staff and patient requests require Super Admin approval. No one can self-register as administrator.</p>':''}<p id="account-error" role="alert"></p><button class="btn primary" type="submit">${mode==='signin'?'Sign in':'Create account'}</button></form><p style="margin-top:24px;color:#587078;font-size:13px">Passwords are managed by Supabase Auth. Registration approval and assigned roles are enforced by the application server. Your first sign-in uses your email; your username becomes available after your profile request is saved.</p><p dir="rtl">حساب مستقل للتطبيق. تسجيل المستخدم لا يمنحه صلاحيات قبل موافقة مدير التطبيق.</p>`);screen.querySelector('#account-signin').onclick=()=>{mode='signin';auth()};screen.querySelector('#account-signup').onclick=()=>{mode='signup';auth()};screen.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button'),f=Object.fromEntries(new FormData(form));button.disabled=true;try{if(mode==='signup'){const r=await req('signup','POST',{...f,email:f.login,syntheticOnly:!!f.syntheticOnly});form.reset();notice(r.message)}else{await req('signin','POST',{login:f.login,password:f.password});form.reset();await load()}}catch(e){notice(e.message)}finally{button.disabled=false}}}
async function signout(){try{await req('signout','POST')}catch(e){notice('Sign-out could not be confirmed. Reconnect and retry.');return}window.fnMessages?.reset();current=null;teamSession=null;teamData=null;teamWorkspaceId='';teamVisitId='';mode='signin';auth()}
function links(){return `<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:22px"><button class="btn" id="account-refresh">Refresh status</button>${current?.status==='approved'?'<button class="btn" id="account-messages">Messages & calls</button>':''}<button class="btn" id="account-logout">Sign out</button></div><p id="account-error" role="alert"></p>`}
function wireLinks(){const msg=screen.querySelector('#account-messages');if(msg)msg.onclick=()=>window.fnMessages.open();screen.querySelector('#account-refresh').onclick=load;screen.querySelector('#account-logout').onclick=signout}
function enroll(){panel(`<h2>Complete your registration request</h2><p>Signed in as ${esc(current.email)}. Your access stays blocked until the Super Admin approves.</p><form>${fields()}<p id="account-error" role="alert"></p><button class="btn primary" type="submit">Submit for approval</button></form>${links()}`);wireLinks();screen.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=Object.fromEntries(new FormData(e.target));await req('enroll','POST',{...f,syntheticOnly:!!f.syntheticOnly});await load()}catch(e){notice(e.message);b.disabled=false}}}
function waiting(){panel(`<h2>${current.status==='pending'?'Awaiting administrator approval':current.status==='suspended'?'Account suspended':'Request not approved'}</h2><p><strong>${esc(current.account?.label)}</strong> · ${esc(current.account?.username)}</p><p>Requested role: ${esc(current.account?.requestedRole)}</p><div class="notice">Clinical workspaces are unavailable while your account is ${esc(current.status)}.</div>${current.account?.reason?`<p>Administrator feedback: ${esc(current.account.reason)}</p>`:''}${links()}`);wireLinks()}
async function patient(){panel(`<h2>Patient portal</h2><p>${esc(current.account.label)} · ${esc(current.account.externalId)}</p><div id="patient-view">Loading your assigned synthetic visit…</div>${links()}`);wireLinks();try{const r=await req('patient');screen.querySelector('#patient-view').innerHTML=r.linked?`<div class="notice">Synthetic training visit · ${esc(r.caseCode)}</div><p>Care stage: ${esc(teamStages[r.stage]?.label||r.stage)}</p><p>Triage: ${esc(fmt(r.triageAt))}</p>${r.dose?`<p>Documented synthetic regimen: ${esc(r.dose.regimen)}<br>Documented at ${esc(fmt(r.dose.administeredAt))}</p>`:'<p>No dose administration is documented.</p>'}<p>Follow-up scheduling and patient messaging are not connected.</p>`:'<div class="notice">No visit is linked yet. Your administrator must verify and assign your fictional Patient ID. Staff lists and other patients are unavailable.</div>'}catch(e){notice(e.message)}}
function staff(){panel(`<h2>${current.role==='superadmin'?'Application owner · Super Admin':'Your workspace'}</h2><p>${esc(current.account?.label||current.label)} · ${esc(current.role)}</p><p>${current.role==='superadmin'?'Review registrations, assign roles and manage your synthetic hospital.':'Your assigned role controls actions on the server.'}</p><div style="display:flex;gap:10px;flex-wrap:wrap">${current.role==='superadmin'?'<button class="btn primary" id="open-admin">Registration requests</button>':''}<button class="btn" id="open-team">Open team workspace</button><button class="btn" id="open-clinical">Open synthetic clinical workspace</button></div>${links()}`);wireLinks();if(current.role==='superadmin')screen.querySelector('#open-admin').onclick=admin;screen.querySelector('#open-team').onclick=()=>{visible(false);go('Team workspace')};screen.querySelector('#open-clinical').onclick=()=>visible(false)}
async function admin(){panel('<h2>Loading registration requests…</h2>',true);try{adminData=await req('requests');renderAdmin()}catch(e){panel(`<h2>Could not load requests</h2><p role="alert">${esc(e.message)}</p>${links()}`,true);wireLinks()}}
function renderAdmin(){const d=adminData;panel(`<div class="sectiontitle"><div><h2>Registration requests</h2><p>${d.accounts.filter(a=>a.status==='pending').length} pending · ${d.accounts.length} accounts loaded (latest 200)</p></div><button class="btn" id="admin-back">My account</button></div><div class="notice">In-app approval inbox is active. Email notifications are not connected. Passwords are never shown to administrators.</div>${d.teams.length?'':'<p>Create your first fictional hospital from <strong>Open team workspace → Create demo hospital</strong> before approving staff.</p>'}<div style="overflow:auto;margin-top:20px"><table><thead><tr><th>User / ID</th><th>Requested / assigned role</th><th>Status</th><th>Review</th></tr></thead><tbody>${d.accounts.map((a,i)=>`<tr><td><strong>${esc(a.label)}</strong><br>${esc(a.username)} · ${esc(a.email)}<br><small>ID: ${esc(a.external_id)}</small></td><td>${esc(a.requested_role)}<br>${esc(a.role||'Unassigned')}</td><td><span class="pill ${a.status==='approved'?'':'amber'}">${esc(a.status)}</span></td><td><button class="btn" data-review="${i}">Review account</button></td></tr>`).join('')||'<tr><td colspan="4">No registration requests yet. New users must verify their email if required, sign in, then submit their profile for approval.</td></tr>'}</tbody></table></div><details style="margin-top:24px"><summary>Approval audit · latest 100 events</summary>${d.events.map(e=>`<p>${esc(fmt(e.at))} · ${esc(e.action)}<br><small>Actor ${esc(e.actor_id)} → ${esc(e.target_id)}</small><br>${esc(e.note)}</p>`).join('')||'<p>No approval events yet.</p>'}</details>${links()}`,true);wireLinks();screen.querySelector('#account-refresh').onclick=admin;screen.querySelector('#admin-back').onclick=staff;screen.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(Number(b.dataset.review)))}
function review(i){const a=adminData.accounts[i];panel(`<h2>Review ${esc(a.label)}</h2><p>${esc(a.username)} · ${esc(a.email)}<br>Requested: ${esc(a.requested_role)} · Provided ID: ${esc(a.external_id)}</p><p>Verify the applicant and ID before granting access. Patient IDs are requests, not proof of ownership.</p><form><label class="field">Decision<select name="status"><option value="approved">Approve / update access</option><option value="rejected">Reject</option><option value="suspended">Suspend</option></select></label><label class="field">Assigned role<select name="role">${['physician','nurse','pharmacist','patient'].map(r=>`<option ${r===(a.role||a.requested_role)?'selected':''}>${r}</option>`).join('')}</select></label><label class="field">Workspace (required for staff)<select name="workspaceId"><option value="">No workspace</option>${adminData.teams.map(t=>`<option value="${t.id}" ${t.id===a.workspace_id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="field">Assigned patient visit (patient role only)<select name="patientVisitId"><option value="">Not linked yet</option>${adminData.visits.map(v=>`<option value="${v.id}" ${v.id===a.patient_visit_id?'selected':''}>${esc(v.case_code)} · ${v.id.slice(0,8)}</option>`).join('')}</select></label><label class="field">Decision reason<textarea name="reason" maxlength="600" required></textarea></label><p id="account-error" role="alert"></p><button class="btn primary" type="submit">Save decision</button> <button class="btn" type="button" id="review-back">Back</button></form>`);screen.querySelector('#review-back').onclick=renderAdmin;screen.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=Object.fromEntries(new FormData(e.target));await req('review','POST',{...f,id:a.id,revision:a.revision});await admin()}catch(e){notice(e.message);b.disabled=false}}}
async function load(){panel('<h2>Checking your application account…</h2>');try{current=await req('session');if(!current){mode='signin';auth()}else if(current.status==='unregistered')enroll();else if(current.status!=='approved')waiting();else if(current.role==='patient')await patient();else staff()}catch(e){panel(`<h2>Account service unavailable</h2><p role="alert">${esc(e.message)}</p><button class="btn" id="access-retry">Retry</button>`);screen.querySelector('button').onclick=load}}
const button=document.createElement('button');button.className='btn';button.textContent='My account';button.onclick=load;document.querySelector('.top').append(button);
/* Recheck approval on focus and before rendering clinical routes. */
window.addEventListener('focus',()=>{if(screen.hidden)load()});
window.fnAccount={load,signout,admin,isOwner:()=>current?.role==='superadmin'};load();
})();
